<?php
declare( strict_types=1 );
namespace Amanah\SEOEngine\Infrastructure\Repository;
use Amanah\SEOEngine\Application\Repository\PageBlueprintRepositoryInterface;
use Amanah\SEOEngine\Domain\PageBlueprint\PageBlueprint;
defined( 'ABSPATH' ) || exit;
final class WordPressPageBlueprintRepository extends WordPressRepository implements PageBlueprintRepositoryInterface { public function __construct(\wpdb $wpdb){parent::__construct($wpdb,$wpdb->prefix.'amanah_seo_page_blueprints');} public function save(PageBlueprint $b):PageBlueprint{$data=array('keyword_id'=>$b->getKeywordId(),'content_brief_id'=>$b->getContentBriefId(),'blueprint_data'=>wp_json_encode($b->getData()),'version'=>$b->getVersion(),'status'=>$b->getStatus(),'created_at'=>current_time('mysql',true),'updated_at'=>current_time('mysql',true));$formats=array('%d','%d','%s','%d','%s','%s','%s');if(null!==$b->getId()){if(false===$this->wpdb->update($this->table,$data,array('id'=>$b->getId()),$formats,array('%d')))throw new \RuntimeException('Page Blueprint could not be stored.');return $b;}if(false===$this->wpdb->insert($this->table,$data,$formats))throw new \RuntimeException('Page Blueprint could not be stored.');return new PageBlueprint($b->getKeywordId(),$b->getData(),$b->getVersion(),$b->getStatus(),$b->getContentBriefId(),(int)$this->wpdb->insert_id);} public function findById(int $id):?PageBlueprint{$row=$this->wpdb->get_row($this->wpdb->prepare("SELECT * FROM {$this->table} WHERE id = %d LIMIT 1",$id),ARRAY_A);return $this->hydrate(is_array($row)?$row:null);} public function findByKeywordId(int $keyword_id):?PageBlueprint{$row=$this->wpdb->get_row($this->wpdb->prepare("SELECT * FROM {$this->table} WHERE keyword_id = %d ORDER BY version DESC, id DESC LIMIT 1",$keyword_id),ARRAY_A);return $this->hydrate(is_array($row)?$row:null);} public function findAll(int $limit=100):array{$limit=max(1,min(100,$limit));$rows=$this->wpdb->get_results($this->wpdb->prepare("SELECT * FROM {$this->table} ORDER BY id DESC LIMIT %d",$limit),ARRAY_A);$items=array();foreach($rows as $row){$b=$this->hydrate(is_array($row)?$row:null);if(null!==$b)$items[]=$b;}return $items;} private function hydrate(?array $row):?PageBlueprint{if(null===$row)return null;$data=json_decode((string)$row['blueprint_data'],true);return new PageBlueprint((int)$row['keyword_id'],is_array($data)?$data:array(),(int)$row['version'],(string)$row['status'],isset($row['content_brief_id'])?(int)$row['content_brief_id']:null,(int)$row['id']);}}
